class Solution:
    def minimumCoverPoints(self, intervals: list[list[int]]) -> list[int]:
        intervals = sorted(intervals, key=lambda x: (x[1], x[0]))
        ans = []
        last = None
        for s, e in intervals:
            if last is None or last < s:
                last = e
                ans.append(last)
        return ans

